  // Flux aggregates PER SERIES and every tag is part of the group key,
  // so this collapses them all into one table first. Without it the panel
  // shows one row per plan/card/region combination instead of a total.
  |> group()
  |> sum()
  |> map(fn: (r) => ({ r with _value: r._value / 100.0 }))

